async function writeDatabase(database: Database): Promise<void> {
  const slash = Math.max(databasePath.lastIndexOf("/"), databasePath.lastIndexOf("\\"));
  const directory = slash < 0 ? "." : databasePath.slice(0, slash) || "/";
