  if (args.length !== 1 || !/^\d+$/.test(args[0])) fail("expected one positive integer task ID");
  const id = Number(args[0]);
  if (!Number.isSafeInteger(id) || id <= 0) fail("expected one positive integer task ID");
  return id;
